@php
 $u=auth()->user();
 $products=\App\Models\Product::where('seller_id',$u->id)->where('status','active')->get();
 $sales=\Illuminate\Support\Facades\DB::table('commerce_flash_sales')->where('seller_id',$u->id)->get();
