<div class="card" id="flash-sales"><div class="card-head"><h2>Schedule a flash sale</h2></div><div class="card-pad"><p>Schedule times use {{ config('app.timezone') }}. Quantity cannot exceed stock. Overlapping sales for the same product are blocked.</p><form style="display:grid;gap:12px" method="POST" action="{{ route('seller.commerce.flash') }}">@csrf<label class="form-row">Product<select class="select" name="product_id" required>@foreach($products as $product)<option value="{{ $product->id }}">{{ $product->name }} ({{ $product->total_stock }} units)</option>@endforeach</select></label><div class="form-grid-2"><label class="form-row">Flash unit price<input type="number" name="price" min="1" step="0.01" required></label><label class="form-row">Flash quantity<input type="number" name="quantity" min="1" max="99999" required></label><label class="form-row">Starts<input type="datetime-local" name="starts_at" required></label><label class="form-row">Ends<input type="datetime-local" name="ends_at" required></label></div><button class="btn btn-primary">Schedule sale</button></form>@foreach($sales as $sale)<div style="padding:12px 0;border-top:1px solid var(--border)">Product {{ $sale->product_id }} · ₱{{ number_format($sale->price,2) }} · {{ $sale->starts_at }}–{{ $sale->ends_at }} @if($sale->is_active)<form style="display:grid;gap:12px" method="POST" action="{{ route('seller.commerce.end',['flash',$sale->id]) }}">@csrf<button class="btn btn-primary">End now</button></form>@else Ended @endif</div>@endforeach</div></div>
